param()
$ErrorActionPreference = "Continue"
$env:GIT_TERMINAL_PROMPT = "0"

$Root = Join-Path $env:USERPROFILE "HeavenBridge"
$Repo = Join-Path $Root "relay"
$JobsRoot = Join-Path $Root "jobs"
$LocksRoot = Join-Path $Root "locks"
$LogFile = Join-Path $Root "worker.log"
$RepoUrl = "https://github.com/fengie/mhw-mods.git"
$Branch = "agent-bridge"
$PollSeconds = 15

New-Item -ItemType Directory -Force -Path $Root,$JobsRoot,$LocksRoot | Out-Null

$createdNew = $false
$mutex = New-Object System.Threading.Mutex($true, "Local\HeavenBridgeWorker", [ref]$createdNew)
if (-not $createdNew) { exit 0 }

function Log([string]$Message) {
    $line = "$(Get-Date -Format o) $Message"
    Add-Content -Path $LogFile -Value $line
}

function Sync-Relay {
    if (-not (Test-Path (Join-Path $Repo ".git"))) {
        Log "Cloning isolated relay checkout."
        & git clone --branch $Branch --single-branch $RepoUrl $Repo 2>&1 | ForEach-Object { Log "$_" }
        if ($LASTEXITCODE -ne 0) { throw "git clone failed: $LASTEXITCODE" }
        & git -C $Repo config user.name "Heaven Bridge Worker"
        & git -C $Repo config user.email "heaven-bridge@local"
    } else {
        & git -C $Repo fetch origin $Branch 2>&1 | ForEach-Object { Log "$_" }
        if ($LASTEXITCODE -ne 0) { throw "git fetch failed: $LASTEXITCODE" }
        & git -C $Repo checkout $Branch 2>&1 | ForEach-Object { Log "$_" }
        & git -C $Repo pull --rebase origin $Branch 2>&1 | ForEach-Object { Log "$_" }
        if ($LASTEXITCODE -ne 0) {
            & git -C $Repo rebase --abort 2>$null
            throw "git pull --rebase failed: $LASTEXITCODE"
        }
    }
}

function Push-Result([string]$Id, [hashtable]$Result) {
    $resultDir = Join-Path $Repo "heaven-bridge\results"
    New-Item -ItemType Directory -Force -Path $resultDir | Out-Null
    $path = Join-Path $resultDir "$Id.json"
    $Result | ConvertTo-Json -Depth 8 | Set-Content -Path $path -Encoding UTF8

    & git -C $Repo add -- "heaven-bridge/results/$Id.json"
    & git -C $Repo commit -m "heaven-bridge: result $Id" 2>&1 | ForEach-Object { Log "$_" }
    if ($LASTEXITCODE -ne 0) {
        Log "No new result commit for $Id or commit failed; continuing to sync/push."
    }

    & git -C $Repo pull --rebase origin $Branch 2>&1 | ForEach-Object { Log "$_" }
    if ($LASTEXITCODE -ne 0) {
        & git -C $Repo rebase --abort 2>$null
        throw "result rebase failed"
    }

    & git -C $Repo push origin $Branch 2>&1 | ForEach-Object { Log "$_" }
    if ($LASTEXITCODE -ne 0) { throw "result push failed: $LASTEXITCODE" }
}

function Tail-Text([string]$Path, [int]$MaxChars = 16000) {
    if (-not (Test-Path $Path)) { return "" }
    $s = Get-Content -Raw -Path $Path -ErrorAction SilentlyContinue
    if ($null -eq $s) { return "" }
    if ($s.Length -gt $MaxChars) { return $s.Substring($s.Length - $MaxChars) }
    return $s
}

function Run-Job($Job, [string]$QueuePath) {
    $id = [string]$Job.id
    $started = (Get-Date).ToString("o")
    $work = Join-Path $JobsRoot $id
    New-Item -ItemType Directory -Force -Path $work | Out-Null
    $outFile = Join-Path $work "codex-output.txt"
    $promptFile = Join-Path $work "prompt.txt"

    if ($Job.target -ne "heaven") { throw "unsupported target: $($Job.target)" }
    if ($Job.kind -eq "health") {
        $result = @{
            id = $id
            status = "completed"
            host = "heaven"
            summary = "Heaven Local Bridge worker is online."
            artifacts = @()
            tests = @("queue-consume","result-publish")
            errors = @()
            exit_code = 0
            queue_file = (Split-Path $QueuePath -Leaf)
            started_at = $started
            finished_at = (Get-Date).ToString("o")
            bridge_version = 1
        }
        Push-Result -Id $id -Result $result
        Log "Finished health job $id"
        return
    }
    if ($Job.kind -ne "codex") { throw "unsupported kind: $($Job.kind)" }
    if ([string]::IsNullOrWhiteSpace([string]$Job.prompt)) { throw "empty prompt" }

    $wrapped = @"
You are the local execution worker named heaven.
This job came from the user's private Heaven Local Bridge.
Perform the task concretely; do not merely summarize or hand it back.
Use the configured local Desktop Commander MCP for local filesystem/process work when useful.
Keep heavy builds/tests/scans/agent work on this machine.
For repository work, use an isolated checkout or feature branch. Do not treat this relay checkout as the canonical dev checkout.
Do not print or commit secrets. Keep heaven2 as the credential/control authority.
Working directory for this job is: $work
CWD hint from dispatcher: $($Job.cwd_hint)

USER TASK:
$($Job.prompt)
"@
    Set-Content -Path $promptFile -Value $wrapped -Encoding UTF8

    Log "Starting job $id"
    Push-Location $work
    try {
        Get-Content -Raw $promptFile |
            & codex exec --skip-git-repo-check --sandbox workspace-write - 2>&1 |
            Tee-Object -FilePath $outFile | Out-Null
        $exitCode = $LASTEXITCODE
    } finally {
        Pop-Location
    }

    $summary = Tail-Text $outFile
    $status = if ($exitCode -eq 0) { "completed" } else { "failed" }
    $errors = @()
    if ($exitCode -ne 0) { $errors += "Codex exited with code $exitCode" }

    $result = @{
        id = $id
        status = $status
        host = "heaven"
        summary = $summary
        artifacts = @($work)
        tests = @()
        errors = $errors
        exit_code = $exitCode
        queue_file = (Split-Path $QueuePath -Leaf)
        started_at = $started
        finished_at = (Get-Date).ToString("o")
        bridge_version = 1
    }
    Push-Result -Id $id -Result $result
    Log "Finished job $id status=$status exit=$exitCode"
}

try {
    Log "Worker starting."
    Sync-Relay
    while ($true) {
        try {
            Sync-Relay
            $queueDir = Join-Path $Repo "heaven-bridge\queue"
            $resultDir = Join-Path $Repo "heaven-bridge\results"
            New-Item -ItemType Directory -Force -Path $queueDir,$resultDir | Out-Null

            $jobs = Get-ChildItem -Path $queueDir -Filter "*.json" -File | Sort-Object Name
            foreach ($q in $jobs) {
                $id = [IO.Path]::GetFileNameWithoutExtension($q.Name)
                $resultPath = Join-Path $resultDir "$id.json"
                if (Test-Path $resultPath) { continue }

                $lockPath = Join-Path $LocksRoot "$id.lock"
                try {
                    $lock = [IO.File]::Open($lockPath, [IO.FileMode]::CreateNew, [IO.FileAccess]::Write, [IO.FileShare]::None)
                    $lock.Close()
                } catch {
                    continue
                }

                try {
                    $job = Get-Content -Raw $q.FullName | ConvertFrom-Json
                    Run-Job -Job $job -QueuePath $q.FullName
                } catch {
                    Log "Job $id failed before completion: $($_.Exception.Message)"
                    $result = @{
                        id = $id
                        status = "failed"
                        host = "heaven"
                        summary = ""
                        artifacts = @()
                        tests = @()
                        errors = @($_.Exception.Message)
                        started_at = (Get-Date).ToString("o")
                        finished_at = (Get-Date).ToString("o")
                        bridge_version = 1
                    }
                    try { Push-Result -Id $id -Result $result } catch { Log "Could not publish failure result for ${id}: $($_.Exception.Message)" }
                } finally {
                    Remove-Item $lockPath -Force -ErrorAction SilentlyContinue
                }
            }
        } catch {
            Log "Loop error: $($_.Exception.Message)"
        }
        Start-Sleep -Seconds $PollSeconds
    }
} finally {
    Log "Worker exiting."
    if ($createdNew) { $mutex.ReleaseMutex() | Out-Null }
    $mutex.Dispose()
}
